<script setup>definePageMeta({middleware:'auth'});const id=useRoute().params.id;const {data,refresh}=await useFetch(`/api/cards/${id}`);const answers=reactive({});const score=ref(null);await $fetch(`/api/cards/${id}/read`,{method:'POST'}).catch(()=>{});async function submit(){const r=await $fetch(`/api/cards/${id}/quiz`,{method:'POST',body:{answers}});score.value=r;refresh()}const comment=ref('');async function send(){await $fetch(`/api/cards/${id}/comments`,{method:'POST',body:{body:comment.value}});comment.value='';refresh()}</script><template><main class="max-w-4xl mx-auto p-7 space-y-6" v-if="data"><section class="panel"><h1 class="text-3xl font-black">{{data.card.title}}</h1><p class="mt-3 whitespace-pre-line">{{data.card.body}}</p><a v-if="data.card.attachment_url" :href="data.card.attachment_url" target="_blank" class="text-blue-700">Buka lampiran</a></section><form class="panel space-y-5" @submit.prevent="submit"><h2 class="text-xl font-black">Kuis Pemahaman · lulus {{data.card.passing_score}}%</h2><div v-for="(q,qi) in data.questions" :key="q.id"><p class="font-semibold">{{qi+1}}. {{q.question}}</p><label v-for="(o,oi) in q.options" :key="oi" class="block"><input type="radio" :name="`q${q.id}`" :value="oi" v-model="answers[q.id]" required> {{o}}</label></div><button class="btn-primary">Submit kuis</button><div v-if="score" class="p-4 rounded-xl" :class="score.done?'bg-green-100':'bg-yellow-100'">Nilai {{score.score}}%. {{score.done?'Done, Anda lulus.':'Belum lulus, silakan ulangi kuis.'}}</div></form><section class="panel"><h2 class="font-black text-xl mb-3">Komentar & pertanyaan</h2><form class="flex gap-2" @submit.prevent="send"><input v-model="comment" class="input" placeholder="Tulis komentar" required><button class="btn-primary">Kirim</button></form><div v-for="c in data.comments" class="border-t mt-4 pt-3"><b>{{c.name}}</b><p>{{c.body}}</p></div></section></main></template>